package dustin.cex.domains.kyc;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import dustin.cex.domains.edd.*;
import dustin.cex.domains.security.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import org.springframework.dao.DataAccessException;
import org.springframework.http.MediaType;
import org.springframework.web.server.ResponseStatusException;

/** 독립 서명으로 고객 후속 권한만 이전하고 원래 금융·STR 권한을 보존하는지 검증한다. */
class CustomerWorkCustodyIntegrationTest extends CustomerWorkTestSupport {
    @Test void approvedTransferMovesOnlyCustomerWorkAndPreservesHistory() throws Exception {
        var before=context(maker);transfer();var after=context(nextPrimary);assertEquals(1,after.generation());assertNotEquals(before.stamp(),after.stamp());assertEquals(List.of(nextPrimary.user().getId(),nextChecker.user().getId()),after.members().stream().map(CustomerWorkCustody.Member::id).toList());
        assertEquals("인계 후에도 보존할 고객 사유",requests.inspect(nextPrimary.user().getId(),nextPrimary.sid(),receipt.id()).rationale());assertEquals(note,notes.list(nextPrimary.user().getId(),nextPrimary.sid(),receipt.id(),0).getFirst());assertEquals(List.of(reply),replies.own(customer.getId(),sid,receipt.id(),0));assertEquals("RECEIVED",requests.own(customer.getId(),sid,receipt.id()).status());assertEquals(1,active());blocked();
    }
    @Test void priorPeopleLoseReasonNotesAndRepliesAuthority() throws Exception {transfer();for(var a:List.of(maker,checker)){assertThrows(ResponseStatusException.class,()->requests.inspect(a.user().getId(),a.sid(),receipt.id()));assertThrows(ResponseStatusException.class,()->notes.list(a.user().getId(),a.sid(),receipt.id(),0));assertThrows(ResponseStatusException.class,()->replies.assigned(a.user().getId(),a.sid(),receipt.id(),0));}}
    @Test void newPeopleDoNotGainOriginalExitOrRescissionAuthority() throws Exception {transfer();assertThrows(ResponseStatusException.class,()->reporting.inspect(nextPrimary.user().getId(),nextPrimary.sid(),original.payload().id(),0));assertThrows(ResponseStatusException.class,()->rescissions.propose(nextPrimary.user().getId(),nextPrimary.sid(),original.payload().id(),independent.user().getId(),UUID.randomUUID(),withdrawalFacts()));assertNotNull(reporting.inspect(maker.user().getId(),maker.sid(),original.payload().id(),0));}
    @Test void pendingAndRejectedTransferDoNotMoveAccess() throws Exception {var r=proposal(maker,UUID.randomUUID());assertThrows(ResponseStatusException.class,()->requests.inspect(nextPrimary.user().getId(),nextPrimary.sid(),receipt.id()));decideHandoff(independent,r,false,handoffProof(independent,r,false));assertEquals(0,context(maker).generation());assertNotNull(requests.inspect(maker.user().getId(),maker.sid(),receipt.id()));}
    @Test void requesterCurrentMembersAndTargetsCannotApprove() throws Exception {var r=proposal(maker,UUID.randomUUID());for(var a:List.of(maker,checker,nextPrimary,nextChecker))assertThrows(ResponseStatusException.class,()->handoffs.inspect(a.user().getId(),a.sid(),r.payload().id()));}
    @Test void outsiderCannotSelfAssignHealthyWork() throws Exception {assertThrows(ResponseStatusException.class,()->context(independent));assertThrows(ResponseStatusException.class,()->handoffs.propose(independent.user().getId(),independent.sid(),receipt.id(),context(maker).stamp(),nextPrimary.user().getId(),nextChecker.user().getId(),UUID.randomUUID(),"임의 인수"));}
    @Test void duplicateSameKeyReplaysButChangedReasonConflicts() throws Exception {UUID key=UUID.randomUUID();var r=proposal(maker,key);assertEquals(r,proposal(maker,key));assertThrows(ResponseStatusException.class,()->handoffs.propose(maker.user().getId(),maker.sid(),receipt.id(),context(maker).stamp(),nextPrimary.user().getId(),nextChecker.user().getId(),key,"다른 사유"));}
    @Test void unchangedPeopleAndSameHumanTargetsAreRejected() throws Exception {var c=context(maker);assertThrows(ResponseStatusException.class,()->handoffs.propose(maker.user().getId(),maker.sid(),receipt.id(),c.stamp(),maker.user().getId(),checker.user().getId(),UUID.randomUUID(),"변경 없는 배정"));var u=users.findById(nextChecker.user().getId()).orElseThrow();u.setOperatorPersonId(nextPrimary.user().getOperatorPersonId());users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->proposal(maker,UUID.randomUUID()));}
    @Test void ownInspectionIsRequiredForOptions() throws Exception {var r=proposal(maker,UUID.randomUUID());assertThrows(ResponseStatusException.class,()->handoffs.options(independent.user().getId(),independent.sid(),r.payload().id(),r.payloadHash(),true));}
    @Test void oppositeDecisionAndOtherBusinessProofCannotAuthorizeTransfer() throws Exception {var r=proposal(maker,UUID.randomUUID());var proof=handoffProof(independent,r,true);assertThrows(ResponseStatusException.class,()->decideHandoff(independent,r,false,proof));var o=new org.springframework.transaction.support.TransactionTemplate(manager).execute(t->{mfa.bindApproval(OperatorMfaService.ApprovalKind.STR_CUSTODY,r.payload().id(),maker.user().getId(),r.payload().requesterVersion(),r.payloadHash(),r.payload().expiresAt());return mfa.approvalOptions(independent.user().getId(),independent.sid(),OperatorMfaService.ApprovalKind.STR_CUSTODY,r.payload().id(),r.payloadHash(),true);});var other=new OperatorMfaService.AuthorizationProof(o.challengeId(),independent.key().assertion(o,"http://localhost:3003",true,counter.incrementAndGet(),null));assertThrows(ResponseStatusException.class,()->decideHandoff(independent,r,true,other));}
    @Test void targetVersionChangeInvalidatesSignedRequestWithoutConsumingProof() throws Exception {var r=proposal(maker,UUID.randomUUID());var proof=handoffProof(independent,r,true);var u=users.findById(nextPrimary.user().getId()).orElseThrow();u.setUsername("버전 변경");users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->decideHandoff(independent,r,true,proof));assertEquals(0,context(maker).generation());}
    @Test void requesterVersionChangeInvalidatesRequest() throws Exception {var r=proposal(maker,UUID.randomUUID());var u=users.findById(maker.user().getId()).orElseThrow();u.setUsername("버전 변경");users.saveAndFlush(u);assertThrows(ResponseStatusException.class,()->handoffs.inspect(independent.user().getId(),independent.sid(),r.payload().id()));}
    @Test void proposalAuditFailureRollsBackRequestAndBinding() throws Exception {doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_WORK_CUSTODY_PROPOSED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->proposal(maker,UUID.randomUUID()));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_work_custody_requests WHERE review_id=?",Long.class,receipt.id()));reset(audit);assertNotNull(proposal(maker,UUID.randomUUID()));}
    @Test void viewAuditFailureDoesNotProvideAssignmentReason() throws Exception {var r=proposal(maker,UUID.randomUUID());doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_WORK_CUSTODY_VIEWED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->handoffs.inspect(independent.user().getId(),independent.sid(),r.payload().id()));reset(audit);assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM customer_work_custody_views WHERE request_id=?",Long.class,r.payload().id()));}
    @Test void decisionAuditFailureRestoresProofAndSameProofRetries() throws Exception {var r=proposal(maker,UUID.randomUUID());var proof=handoffProof(independent,r,true);doThrow(new IllegalStateException("격리 감사 실패")).when(audit).record(any(),eq("CUSTOMER_WORK_CUSTODY_DECIDED"),anyString(),anyString(),anyString());assertThrows(IllegalStateException.class,()->decideHandoff(independent,r,true,proof));reset(audit);assertEquals(0,context(maker).generation());assertEquals("APPROVED",decideHandoff(independent,r,true,proof).status());}
    @Test void approvalAndRejectionRaceCommitsExactlyOneDecision() throws Exception {var r=proposal(maker,UUID.randomUUID());var yes=handoffProof(independent,r,true);var no=handoffProof(independent,r,false);var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->{start.await();try{decideHandoff(independent,r,true,yes);return true;}catch(ResponseStatusException e){return false;}});var b=pool.submit(()->{start.await();try{decideHandoff(independent,r,false,no);return true;}catch(ResponseStatusException e){return false;}});start.countDown();assertNotEquals(a.get(10,TimeUnit.SECONDS),b.get(10,TimeUnit.SECONDS));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM customer_work_custody_decisions WHERE request_id=?",Long.class,r.payload().id()));}finally{pool.shutdownNow();}}
    @Test void resultAfterResponseLossIsReadableWithoutAnotherTransfer() throws Exception {var r=proposal(maker,UUID.randomUUID());decideHandoff(independent,r,true,handoffProof(independent,r,true));assertEquals("APPROVED",handoffs.status(maker.user().getId(),maker.sid(),r.payload().id()).status());assertEquals("APPROVED",handoffs.status(independent.user().getId(),independent.sid(),r.payload().id()).status());assertEquals(1,context(nextPrimary).generation());}
    @Test void newOwnerMustObtainOwnReasonBeforeNewNotesOrReplies() throws Exception {transfer();assertThrows(ResponseStatusException.class,()->notes.record(nextPrimary.user().getId(),nextPrimary.sid(),receipt.id(),UUID.randomUUID(),new CustomerReviewNoteService.Facts(CustomerReviewNoteService.Progress.INVESTIGATING,"추가 조사")));requests.inspect(nextPrimary.user().getId(),nextPrimary.sid(),receipt.id());var n=notes.record(nextPrimary.user().getId(),nextPrimary.sid(),receipt.id(),UUID.randomUUID(),new CustomerReviewNoteService.Facts(CustomerReviewNoteService.Progress.INVESTIGATING,"추가 조사"));assertNotNull(replies.record(nextPrimary.user().getId(),nextPrimary.sid(),receipt.id(),UUID.randomUUID(),n.id()));assertEquals(1,active());}
    @Test void generationChangeInvalidatesEvenReturningOwnersOldPersonalReceipt() throws Exception {transfer();var c=context(nextPrimary);var r=handoffs.propose(nextPrimary.user().getId(),nextPrimary.sid(),receipt.id(),c.stamp(),maker.user().getId(),checker.user().getId(),UUID.randomUUID(),"원래 담당자로 재인계");decideHandoff(independent,r,true,handoffProof(independent,r,true));assertEquals(2,context(maker).generation());assertThrows(ResponseStatusException.class,()->notes.record(maker.user().getId(),maker.sid(),receipt.id(),UUID.randomUUID(),new CustomerReviewNoteService.Facts(CustomerReviewNoteService.Progress.INVESTIGATING,"옛 제공 재사용")));}
    @Test void allCustodyRecordsRejectUpdateDeleteAndTruncate() throws Exception {var r=proposal(maker,UUID.randomUUID());decideHandoff(independent,r,true,handoffProof(independent,r,true));for(String table:List.of("customer_work_custody_requests","customer_work_custody_views","customer_work_custody_decisions"))for(String sql:List.of("UPDATE "+table+" SET request_id=request_id","DELETE FROM "+table,"TRUNCATE "+table)){if(sql.startsWith("UPDATE customer_work_custody_requests"))sql="UPDATE "+table+" SET id=id";String statement=sql;assertThrows(DataAccessException.class,()->jdbc.execute(statement));}}
    @Test void supervisionUsesCurrentCustodiansRatherThanOriginalPeople() throws Exception {transfer();disable(maker);disable(checker);var item=supervision.queue(independent.user().getId(),independent.sid(),null).items().stream().filter(i->i.requestId().equals(receipt.id())).findFirst();if(item.isEmpty()){var page=supervision.queue(independent.user().getId(),independent.sid(),null);while(page.next()!=null&&item.isEmpty()){page=supervision.queue(independent.user().getId(),independent.sid(),page.next());item=page.items().stream().filter(i->i.requestId().equals(receipt.id())).findFirst();}}assertFalse(item.orElseThrow().orphaned());}
    @Test void legacyApprovalAndUnboundViewSchemasAreRejectedWithoutBackfill() throws Exception {
        var isolated=new org.springframework.transaction.support.TransactionTemplate(manager);isolated.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_REPEATABLE_READ);assertThrows(IllegalStateException.class,()->isolated.execute(t->requests.assignedContext(maker.user().getId(),maker.sid(),receipt.id())));
        new org.springframework.transaction.support.TransactionTemplate(manager).executeWithoutResult(t->{jdbc.execute("ALTER TABLE operator_approval_bindings DROP CONSTRAINT operator_approval_bindings_kind_check");jdbc.execute("ALTER TABLE operator_approval_bindings ADD CONSTRAINT operator_approval_bindings_kind_check CHECK(kind IN ('ROLE','MFA_RECOVERY','ACCESS_REVIEW','TRADING_RESTRICTION','EDD_REVIEW','EDD_ADDRESS_REVIEW','EDD_FUNDS_REVIEW','EDD_WEALTH_REVIEW','STR_REVIEW','STR_CUSTODY','RELATIONSHIP_EXIT','EXIT_RESCISSION')) NOT VALID");assertThrows(Exception.class,()->audit.schema());t.setRollbackOnly();});
        new org.springframework.transaction.support.TransactionTemplate(manager).executeWithoutResult(t->{jdbc.execute("ALTER TABLE customer_exit_review_views DROP COLUMN custody_generation");assertThrows(Exception.class,()->new KycSchemaInitializer(jdbc).initialize());t.setRollbackOnly();});
        assertNotNull(requests.inspect(maker.user().getId(),maker.sid(),receipt.id()));
    }
    @Test void httpTransferAndNewContextWorkWhileOldExitListIsRemoved() throws Exception {var c=context(maker);String body=mvc.perform(post("/api/admin/compliance/customer-custody-requests").header("Authorization","Bearer "+maker.access()).header("Idempotency-Key",UUID.randomUUID()).contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(new CustomerWorkCustodyController.Proposal(receipt.id(),c.stamp(),nextPrimary.user().getId(),nextChecker.user().getId(),"업무 교대")))).andExpect(status().isOk()).andReturn().getResponse().getContentAsString();var r=json.readValue(body,CustomerWorkCustodyService.Request.class);decideHandoff(independent,r,true,handoffProof(independent,r,true));mvc.perform(get("/api/admin/compliance/customer-review-requests/"+receipt.id()+"/context").header("Authorization","Bearer "+nextPrimary.access())).andExpect(status().isOk()).andExpect(jsonPath("$.assignment.generation").value(1));mvc.perform(get("/api/admin/compliance/relationship-exits/"+original.payload().id()+"/review-requests").header("Authorization","Bearer "+maker.access())).andExpect(status().isForbidden());}
}
